"use client";
import { useState } from "react";

export default function Newsletter() {
  return (
    <section className="bg-[#2e2e2b] py-20 text-center text-white mt-20">
      <div className="max-w-4xl mx-auto px-5">
        <h2 className="text-3xl font-semibold mb-4">
          Subscreve a nossa <span className="text-[#7a9e7a]">newsletter</span>
        </h2>
        <p className="mb-8 text-[#9a9a94]">
          Recebe novidades, coleções exclusivas e ofertas especiais diretamente no teu email.
        </p>
        <form className="flex flex-col sm:flex-row justify-center gap-2 mb-4">
          <input 
            type="email" 
            placeholder="O teu endereço de email" 
            className="bg-[#3e3e3b] px-4 py-2 rounded outline-none w-full sm:w-64 text-white border border-[#5c7a5c]" 
            required
          />
          <button type="submit" className="bg-[#5c7a5c] px-6 py-2 rounded font-medium hover:bg-[#4a644a] transition-colors">
            Subscrever
          </button>
        </form>
        <p className="text-[12px] text-[#7a9e7a]">Sem spam. Podes cancelar a qualquer momento.</p>
      </div>
    </section>
  );
}